import { getAllProducts } from '@/lib/db';
import { cacheTag, revalidateTag } from 'next/cache';
import { Suspense } from 'react';

interface Product {
  id: number;
  name: string;
  price: number;
}

async function ProductList() {
  'use cache';
  cacheTag('products');

  const products = await getAllProducts();
  const timestamp = new Date().toLocaleTimeString();

  return (
    <div className="p-4 border rounded-lg shadow-sm">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-xl font-semibold">Product List</h2>
        <span className="text-sm text-gray-500">Cached at: {timestamp}</span>
      </div>
      <ul className="space-y-2">
        {products.map((product: Product) => (
          <li key={product.id} className="flex justify-between p-2 hover:bg-gray-50 rounded">
            <span>{product.name}</span>
            <span className="font-mono">${product.price}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default function Page() {
  async function invalidateProducts() {
    'use server';
    revalidateTag('products');
  }

  return (
    <div className="max-w-2xl mx-auto p-8 space-y-8">
      <h1 className="text-3xl font-bold">Cached Products Demo</h1>

      <Suspense fallback={<div className="p-4 text-center">Loading products...</div>}>
        <ProductList />
      </Suspense>

      <div className="p-4 bg-gray-50 rounded-lg border">
        <h3 className="font-medium mb-2">Cache Controls</h3>
        <p className="text-sm text-gray-600 mb-4">
          Submitting the form below will invalidate the "products" cache tag, 
          causing the list to refresh with a new timestamp.
        </p>
        <form action={invalidateProducts}>
          <button 
            type="submit"
            className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors"
          >
            Invalidate Cache
          </button>
        </form>
      </div>
    </div>
  );
}
